shell_commands:
node -e "
const fs = require('fs');
const path = require('path');
const dir = path.join(path.dirname(require.resolve('@re-cinq/eslint-plugin-re-lint')), 'rules');
console.log('Rules:', fs.readdirSync(dir));
for (const name of ['require-colocated-tests.mjs', 'test-imports-its-subject.mjs', 'require-spec-link.mjs', 'max-expects.mjs', 'require-status-matches-coverage.mjs']) {
  if (fs.existsSync(path.join(dir, name))) {
    console.log('=== ' + name + ' ===');
    console.log(fs.readFileSync(path.join(dir, name), 'utf8'));
  }
}
"

